1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	    margin-bottom: 10px;
38	  }
39	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
40	  .p-I { background-color: #22d3ee; }
41	  .p-O { background-color: #facc15; }
42	  .p-T { background-color: #a855f7; }
43	  .p-S { background-color: #22c55e; }
44	  .p-Z { background-color: #ef4444; }
45	  .p-J { background-color: #3b82f6; }
46	  .p-L { background-color: #f97316; }
47	  .panel { width: 160px; }
48	  .stat { margin-bottom: 14px; }
49	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
50	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
51	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
52	  .overlay {
53	    position: absolute;
54	    inset: 0;
55	    display: flex;
56	    flex-direction: column;
57	    align-items: center;
58	    justify-content: center;
59	    background: rgba(17, 24, 39, 0.8);
60	    font-size: 22px;
61	    font-weight: 600;
62	  }
63	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board-wrap">
69	    <div class="board" id="board" data-testid="board"></div>
70	    <div class="overlay" id="overlay" hidden>Game over<small>Press Enter to play again</small></div>
71	  </div>
72	  <div class="panel">
73	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
74	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
75	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
76	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
77	    <div class="help">
78	      ← → move<br>
79	      ↑ rotate<br>
80	      ↓ soft drop<br>
81	      Space hard drop<br>
82	      Enter new game
83	    </div>
84	  </div>
85	</div>
86	<script>
87	(function () {
88	  "use strict";
89	
90	  var ROWS = 20;
91	  var COLS = 10;
92	  var PREVIEW = 3;
93	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
94	
95	  // Spawn orientation of each piece inside its rotation box.
96	  var SHAPES = {
97	    I: ["....", "IIII", "....", "...."],
98	    O: ["OO", "OO"],
99	    T: [".T.", "TTT", "..."],
100	    S: [".SS", "SS.", "..."],
101	    Z: ["ZZ.", ".ZZ", "..."],
102	    J: ["J..", "JJJ", "..."],
103	    L: ["..L", "LLL", "..."]
104	  };
105	
106	  // Scoring (decision): points for rows cleared at once, times level. Clearing rows
107	  // together always beats clearing them one at a time. Soft drop 1 per cell, hard drop 2.
108	  var LINE_POINTS = [0, 100, 300, 500, 800];
109	  var SOFT_DROP_POINTS = 1;
110	  var HARD_DROP_POINTS = 2;
111	
112	  var state = {
113	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
114	    current: null,  // { type, matrix, row, col }
115	    next: [],
116	    bag: [],
117	    score: 0,
118	    level: 1,
119	    lines: 0,
120	    status: "running"
121	  };
122	
123	  var timer = null;
124	
125	  // ---------- pieces ----------
126	
127	  function isType(t) { return TYPES.indexOf(t) !== -1; }
128	
129	  function randomType() {
130	    if (state.bag.length === 0) {
131	      var bag = TYPES.slice();
132	      for (var i = bag.length - 1; i > 0; i--) {
133	        var j = Math.floor(Math.random() * (i + 1));
134	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
135	      }
136	      state.bag = bag;
137	    }
138	    return state.bag.pop();
139	  }
140	
141	  function cleanQueue(queue) {
142	    if (!Array.isArray(queue)) return [];
143	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
144	  }
145	
146	  function fillPreview() {
147	    while (state.next.length < PREVIEW) state.next.push(randomType());
148	  }
149	
150	  function makeMatrix(type) {
151	    return SHAPES[type].map(function (r) { return r.split(""); });
152	  }
153	
154	  function pieceCells(piece) {
155	    var cells = [];
156	    for (var r = 0; r < piece.matrix.length; r++) {
157	      for (var c = 0; c < piece.matrix[r].length; c++) {
158	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
159	      }
160	    }
161	    return cells;
162	  }
163	
164	  function fits(matrix, row, col) {
165	    for (var r = 0; r < matrix.length; r++) {
166	      for (var c = 0; c < matrix[r].length; c++) {
167	        if (matrix[r][c] === ".") continue;
168	        var br = row + r, bc = col + c;
169	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
170	        if (state.board[br][bc] !== ".") return false;
171	      }
172	    }
173	    return true;
174	  }
175	
176	  // [REQ-001] Spawn the next piece at the top of the board.
177	  function spawn() {
178	    var type = state.next.length ? state.next.shift() : randomType();
179	    if (state.next.length === 0) fillPreview();
180	    var matrix = makeMatrix(type);
181	    var top = 0;
182	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
183	    var piece = {
184	      type: type,
185	      matrix: matrix,
186	      row: -top,
187	      col: Math.floor((COLS - matrix[0].length) / 2),
188	      lockTicks: 0,
189	      lockResets: 0
190	    };
191	    if (!fits(piece.matrix, piece.row, piece.col)) {
192	      state.current = null;
193	      state.status = "over";
194	      stopTimer();
195	      return;
196	    }
197	    state.current = piece;
198	  }
199	
200	  // ---------- core rules ----------
201	
202	  // [REQ-003] Remove full rows, drop the rest, score by rows cleared at once times level.
203	  function clearLines() {
204	    var kept = state.board.filter(function (row) {
205	      return row.some(function (ch) { return ch === "."; });
206	    });
207	    var cleared = ROWS - kept.length;
208	    while (kept.length < ROWS) kept.unshift(emptyRow());
209	    state.board = kept;
210	    if (cleared > 0) {
211	      state.score += LINE_POINTS[cleared] * state.level;
212	      state.lines += cleared;
213	      state.level = Math.floor(state.lines / 10) + 1;
214	    }
215	  }
216	
217	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
218	  function lockPiece() {
219	    var p = state.current;
220	    pieceCells(p).forEach(function (cell) {
221	      state.board[cell[0]][cell[1]] = p.type;
222	    });
223	    state.current = null;
224	    clearLines();
225	    spawn();
226	  }
227	
228	  function tryMove(dr, dc) {
229	    var p = state.current;
230	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
231	    p.row += dr;
232	    p.col += dc;
233	    return true;
234	  }
235	
236	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
237	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
238	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece.
239	  var LOCK_DELAY = 2;
240	  var MAX_LOCK_RESETS = 3;
241	
242	  function isResting(p) {
243	    return !fits(p.matrix, p.row + 1, p.col);
244	  }
245	
246	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
247	  // Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
248	  function gravityStep() {
249	    if (state.status !== "running" || !state.current) return false;
250	    var p = state.current;
251	    if (tryMove(1, 0)) {
252	      p.lockTicks = 0;
253	      return true;
254	    }
255	    p.lockTicks++;
256	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
257	    return false;
258	  }
259	
260	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
261	  function shift(dc) {
262	    var p = state.current;
263	    var resting = isResting(p);
264	    if (!tryMove(0, dc)) return;
265	    if (resting && p.lockResets < MAX_LOCK_RESETS) {
266	      p.lockResets++;
267	      p.lockTicks = 0;
268	    }
269	  }
270	
271	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
272	  function rotate() {
273	    var p = state.current;
274	    if (!p) return;
275	    var size = p.matrix.length;
276	    var rotated = [];
277	    for (var r = 0; r < size; r++) {
278	      rotated.push([]);
279	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
280	    }
281	    var kicks = [0, -1, 1, -2, 2];
282	    for (var i = 0; i < kicks.length; i++) {
283	      if (fits(rotated, p.row, p.col + kicks[i])) {
284	        p.matrix = rotated;
285	        p.col += kicks[i];
286	        return;
287	      }
288	    }
289	  }
290	
291	  // [REQ-001] [REQ-003] Player actions; soft and hard drop score per cell moved down.
292	  function input(action) {
293	    if (state.status !== "running" || !state.current) return;
294	    switch (action) {
295	      case "left": shift(-1); break;
296	      case "right": shift(1); break;
297	      case "softDrop":
298	        if (gravityStep()) state.score += SOFT_DROP_POINTS;
299	        break;
300	      case "hardDrop":
301	        var dropped = 0;
302	        while (tryMove(1, 0)) dropped++;
303	        state.score += dropped * HARD_DROP_POINTS;
304	        lockPiece();
305	        break;
306	      case "rotate":
307	      case "rotateCW": rotate(); break;
308	      default: return;
309	    }
310	    render();
311	    restartTimerIfNeeded();
312	  }
313	
314	  // ---------- timer ----------
315	
316	  function gravityInterval() {
317	    return Math.max(100, 1000 - (state.level - 1) * 90);
318	  }
319	
320	  function stopTimer() {
321	    if (timer !== null) { clearTimeout(timer); timer = null; }
322	  }
323	
324	  function startTimer() {
325	    stopTimer();
326	    if (state.status !== "running") return;
327	    timer = setTimeout(function () {
328	      timer = null;
329	      gravityStep();
330	      render();
331	      startTimer();
332	    }, gravityInterval());
333	  }
334	
335	  function restartTimerIfNeeded() {
336	    if (state.status === "running" && timer === null) startTimer();
337	  }
338	
339	  // ---------- setup ----------
340	
341	  function emptyRow() {
342	    var row = [];
343	    for (var c = 0; c < COLS; c++) row.push(".");
344	    return row;
345	  }
346	
347	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
348	  function newGame(queue) {
349	    state.board = [];
350	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
351	    state.bag = [];
352	    state.score = 0;
353	    state.level = 1;
354	    state.lines = 0;
355	    state.status = "running";
356	    state.current = null;
357	    var q = cleanQueue(queue);
358	    state.next = q;
359	    if (q.length === 0) fillPreview();
360	    spawn();
361	    render();
362	    startTimer();
363	  }
364	
365	  // ---------- rendering (synchronous) ----------
366	
367	  var boardEl = document.getElementById("board");
368	  var nextEl = document.getElementById("next");
369	  var scoreEl = document.getElementById("score");
370	  var levelEl = document.getElementById("level");
371	  var linesEl = document.getElementById("lines");
372	  var overlayEl = document.getElementById("overlay");
373	  var cellEls = [];
374	
375	  (function buildBoard() {
376	    for (var r = 0; r < ROWS; r++) {
377	      cellEls.push([]);
378	      for (var c = 0; c < COLS; c++) {
379	        var el = document.createElement("div");
380	        el.className = "cell";
381	        el.setAttribute("data-testid", "cell");
382	        el.setAttribute("data-row", String(r));
383	        el.setAttribute("data-col", String(c));
384	        el.setAttribute("data-filled", "false");
385	        el.setAttribute("data-piece", "");
386	        boardEl.appendChild(el);
387	        cellEls[r].push(el);
388	      }
389	    }
390	  })();
391	
392	  function paintCell(el, type) {
393	    el.className = type ? "cell p-" + type : "cell";
394	    el.setAttribute("data-filled", type ? "true" : "false");
395	    el.setAttribute("data-piece", type || "");
396	  }
397	
398	  function renderPreview() {
399	    nextEl.textContent = "";
400	    state.next.slice(0, PREVIEW).forEach(function (type) {
401	      var grid = document.createElement("div");
402	      grid.className = "mini";
403	      var rows = SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; });
404	      for (var r = 0; r < 2; r++) {
405	        for (var c = 0; c < 4; c++) {
406	          var cell = document.createElement("div");
407	          var ch = rows[r] ? rows[r].charAt(c) : ".";
408	          cell.className = ch === type ? "mini-cell p-" + type : "mini-cell";
409	          cell.setAttribute("data-piece", ch === type ? type : "");
410	          grid.appendChild(cell);
411	        }
412	      }
413	      nextEl.appendChild(grid);
414	    });
415	  }
416	
417	  // [REQ-001] Draw the whole game state into the DOM, immediately.
418	  function render() {
419	    var drawn = state.board.map(function (row) { return row.slice(); });
420	    if (state.current) {
421	      var type = state.current.type;
422	      pieceCells(state.current).forEach(function (cell) {
423	        drawn[cell[0]][cell[1]] = type;
424	      });
425	    }
426	    for (var r = 0; r < ROWS; r++) {
427	      for (var c = 0; c < COLS; c++) {
428	        var ch = drawn[r][c];
429	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
430	      }
431	    }
432	    scoreEl.textContent = String(state.score);
433	    levelEl.textContent = String(state.level);
434	    linesEl.textContent = String(state.lines);
435	    overlayEl.hidden = state.status !== "over";
436	    renderPreview();
437	  }
438	
439	  // ---------- keyboard ----------
440	
441	  document.addEventListener("keydown", function (e) {
442	    var map = {
443	      ArrowLeft: "left",
444	      ArrowRight: "right",
445	      ArrowDown: "softDrop",
446	      ArrowUp: "rotateCW",
447	      " ": "hardDrop"
448	    };
449	    if (e.key === "Enter") {
450	      e.preventDefault();
451	      newGame();
452	      return;
453	    }
454	    if (map[e.key]) {
455	      e.preventDefault();
456	      input(map[e.key]);
457	    }
458	  });
459	
460	  // ---------- test control surface ----------
461	
462	  // [REQ-001]
463	  window.__tetris = {
464	    newGame: function (queue) { newGame(queue); },
465	    setQueue: function (queue) {
466	      state.next = cleanQueue(queue);
467	      render();
468	    },
469	    setBoard: function (rows) {
470	      var board = [];
471	      for (var r = 0; r < ROWS; r++) {
472	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
473	        var row = [];
474	        for (var c = 0; c < COLS; c++) {
475	          var ch = line.charAt(c);
476	          row.push(isType(ch) ? ch : ".");
477	        }
478	        board.push(row);
479	      }
480	      state.board = board;
481	      render();
482	    },
483	    tick: function (n) {
484	      var steps = n === undefined ? 1 : n;
485	      for (var i = 0; i < steps; i++) gravityStep();
486	      render();
487	    },
488	    input: function (action) { input(action); },
489	    getBoard: function () {
490	      return state.board.map(function (row) { return row.join(""); });
491	    },
492	    getState: function () {
493	      return {
494	        current: state.current
495	          ? { type: state.current.type, cells: pieceCells(state.current) }
496	          : null,
497	        next: state.next.slice(),
498	        score: state.score,
499	        level: state.level,
500	        lines: state.lines,
501	        status: state.status
502	      };
503	    }
504	  };
505	
506	  newGame();
507	})();
508	</script>
509	</body>
510	</html>
511

